def build_thematic_business(existing_norms: set[str]):
    entries = []
    seen = set()
    rank = 1

    for row in BUSINESS_ITEMS:
        kind = row[0]
        headword = row[1]
        param = row[2]
        level = row[3]
        msa = row[4]
        eg = row[5]
        domain = row[6]

        norm = norm_vocab(headword)
        if norm in existing_norms or norm in seen:
            continue
        seen.add(norm)

        if kind == "noun":
            gender = param if param in ("m", "f", "mf") else "m"
            art = "El" if gender == "m" else "La"
            ex_es = f"{art} {headword} es un concepto indispensable en el mundo de los negocios."
            ex_ar = f"الـ{msa} مفهوم لا غنى عنه في عالم الأعمال."
            entry = make_noun(headword, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        elif kind == "verb":
            paradigm = param or "ar"
            ex_es = f"Las empresas suelen {headword} para mejorar su rendimiento comercial."
            ex_ar = f"تعتاد الشركات أن {msa} لتحسين أدائها التجاري."
            entry = make_verb(headword, paradigm, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        else:
            ex_es = f"Se aplica {headword} en las operaciones financieras."
            ex_ar = f"يُطبق {msa} في العمليات المالية."
            entry = make_adv(headword, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)

        entries.append(entry)
        rank += 1

    emit_bundle(
        filename="vocab-cv-topic-business.json",
        bundle_slug="cv-topic-business",
        title_ar="معجم الأعمال والتجارة والمال والشركات والتقنية",
        entries=entries
    )
    return len(entries), seen

if __name__ == "__main__":
    count, _ = build_thematic_business(get_existing_norms())
    print(f"Generated {count} entries in vocab-cv-topic-business.json")
